CREATE TABLE IF NOT EXISTS login_logs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, org_id TEXT, ip_address TEXT, user_agent TEXT, success BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_login_logs_user_id ON login_logs(user_id); CREATE INDEX IF NOT EXISTS idx_login_logs_org_id ON login_logs(org_id); CREATE INDEX IF NOT EXISTS idx_login_logs_created_at ON login_logs(created_at);
